<template><AppShell title="查找玩家" back><view class="pad"><view class="search"><AppIcon name="search" :size="20" /><input v-model="userNo" @blur="userNo=$event.detail.value" maxlength="21" placeholder="输入5位用户编号，如 10001" confirm-type="search" @confirm="userNo=$event.detail.value;search()" /><button class="ui-button text-button" :disabled="loading" @click="search">查找</button></view><text class="hint">用户编号固定不变，可在自己或其他玩家的个人主页查看。</text><StateView v-if="searched" :loading="loading" :error="error" :count="items.length" title="未找到玩家" description="请核对完整编号，停用账号不会显示" @retry="search" /><button v-for="item in items" :key="item.id" class="ui-button card player-result" @click="go('shop/index',{id:item.id})"><GameArt avatar :size="52" :type="item.avatar" :src="item.avatar?.startsWith('/')?item.avatar:''" /><view class="stack flex-1"><text class="bold">{{item.nickname}}</text><text class="muted tiny">编号 {{item.userNo}} · IP属地 {{item.ipProvince||'未知'}}</text><PlayerBadges :shop-status="item.shopStatus" :realname-status="item.realnameStatus" /></view><AppIcon name="chevron" :size="16" /></button></view></AppShell></template>
<script setup>
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import PlayerBadges from '../../components/PlayerBadges.vue';import StateView from '../../components/StateView.vue';import {request,go} from '../../lib/api'
const userNo=ref(''),items=ref([]),loading=ref(false),error=ref(''),searched=ref(false)
onLoad(q=>{if(q.userNo){userNo.value=q.userNo;search()}})
async function search(){if(loading.value)return;searched.value=true;items.value=[];error.value='';const value=userNo.value.trim().toUpperCase();if(!/^(?:1[0-9]{4}|KK[0-9]{6,19})$/.test(value)){error.value='请输入5位用户编号，例如 10001';return}loading.value=true;try{const r=await request('/boost/players/search?userNo='+encodeURIComponent(value));items.value=r.items}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<style scoped>.hint{display:block;font-size:12px;line-height:1.7;color:#747985;margin:14px 0 22px}.player-result{display:flex;align-items:center;gap:12px;width:100%;text-align:left;min-height:92px}.player-result .stack{min-width:0}.player-result .tiny{line-height:1.6;white-space:normal}</style>
